package helpers

import (
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

// ServicePackage is the Go package the declared calculator CLI names:
// "go run ./services/calc <command> ... from the host root".
const ServicePackage = "./services/calc"

// ExactFlag is the flag the declared halve command takes, the only command
// of the two that declares it, to keep an odd value's half.
const ExactFlag = "--exact"

// HalveCommand and DoubleCommand are the two commands the declared CLI has.
const (
	HalveCommand  = "halve"
	DoubleCommand = "double"
)

// Operation returns the declared CLI command, and the flags that command
// declares, for the operation phrase a step names. "halves" and "exactly
// halves" both name the declared halve command, the second with the --exact
// flag halve alone declares; "doubles" names the declared double command,
// which declares no flag. The helper only translates the step's phrase into
// the declared invocation; the calculator alone works out what it prints.
func Operation(operation string) (string, []string, error) {
	switch operation {
	case "halves":
		return HalveCommand, nil, nil
	case "exactly halves":
		return HalveCommand, []string{ExactFlag}, nil
	case "doubles":
		return DoubleCommand, nil, nil
	default:
		return "", nil, fmt.Errorf("the declared calculator CLI has no command for the operation %q", operation)
	}
}

// HostRoot is the directory the declared CLI is run from: the root of the
// host module, found by walking up from the test's working directory to the
// go.mod that sits beside docs/ and services/.
func HostRoot() (string, error) {
	dir, err := os.Getwd()
	if err != nil {
		return "", fmt.Errorf("locate the host root: %w", err)
	}
	for {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return dir, nil
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", errors.New("locate the host root: no go.mod at or above the test's working directory")
		}
		dir = parent
	}
}

// Run runs the declared calculator command as a process from the host root
// and returns its stdout verbatim, trailing newline included. It carries the
// step's arguments in and the command's stdout back out; the calculator
// computes the answer.
func Run(command string, args ...string) (string, error) {
	root, err := HostRoot()
	if err != nil {
		return "", err
	}
	argv := append([]string{"run", ServicePackage, command}, args...)
	cmd := exec.Command("go", argv...)
	cmd.Dir = root
	var stdout, stderr strings.Builder
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		return "", fmt.Errorf("go %s (in %s): %w: %s",
			strings.Join(argv, " "), root, err, strings.TrimSpace(stderr.String()))
	}
	return stdout.String(), nil
}

package helpers

import (
	"fmt"
	"regexp"
	"strings"
)

// MatchesOutcome and DoesNotMatchOutcome are the two outcomes the output
// step states literally: whether the step requires its pattern to match
// what the calculator printed, or requires no match.
const (
	MatchesOutcome      = "matches"
	DoesNotMatchOutcome = "does not match"
)

// PrintedOutput is the text the declared CLI printed: the kept stdout
// stripped of the trailing newline the declaration says each of halve and
// double ends its result with. It only trims the line ending; it never
// reads, parses or rewrites what the calculator computed.
func PrintedOutput(stdout string) string {
	return strings.TrimSuffix(strings.TrimSuffix(stdout, "\n"), "\r")
}

// MatchOutput matches the step's pattern, as a Go regular expression,
// against the kept stdout without its trailing newline, and reports whether
// the outcome the step states holds: a match when the step says "matches",
// no match when it says "does not match". The calculator alone produced the
// output; this helper only observes it and compares it against the step's
// pattern.
func MatchOutput(stdout, outcome, pattern string) error {
	if stdout == "" {
		return fmt.Errorf("the calculator kept no output to match %q against: the operation step must run first", pattern)
	}
	printed := PrintedOutput(stdout)
	expression, err := regexp.Compile(pattern)
	if err != nil {
		return fmt.Errorf("the step's pattern %q is not a valid Go regular expression: %w", pattern, err)
	}
	matched := expression.MatchString(printed)
	switch outcome {
	case MatchesOutcome:
		if !matched {
			return fmt.Errorf("the calculator's output %q does not match %q", printed, pattern)
		}
		return nil
	case DoesNotMatchOutcome:
		if matched {
			return fmt.Errorf("the calculator's output %q matches %q", printed, pattern)
		}
		return nil
	default:
		return fmt.Errorf("the output step states no such outcome %q: it is either %q or %q", outcome, MatchesOutcome, DoesNotMatchOutcome)
	}
}

package steps

import (
	"fixture/conceptbodiescases/tests/calc/helpers"
)

//truebdd:concept then "output"
func concept95123e5878d35715c67b1f901cd0d6e1fcafc896021616abdece460efff6ed7e(state *State, args []string) error {
	outcome, pattern := args[0], args[1]

	// Observe only: the operation step already kept the declared command's
	// stdout. Match the step's pattern against that kept output without its
	// trailing newline and require the outcome the step states — a match for
	// "matches", no match for "does not match". The calculator alone worked
	// out what it printed; nothing here halves, doubles or otherwise
	// reproduces the result being checked.
	return helpers.MatchOutput(state.Output, outcome, pattern)
}

package steps

import (
	"fixture/conceptbodiescases/tests/calc/helpers"
)

//truebdd:concept when "operation"
func conceptcc0034864638b337019c005041b6023fc84395f3cfcb85aa7757c1b208c55d6e(state *State, args []string) error {
	operation, number := args[0], args[1]

	// The step's operation phrase names which declared command to run and
	// whether the declared halve command gets its --exact flag; the phrase
	// "exactly doubles" can no longer reach here, so no body-side rejection
	// of an unmeant step form remains.
	command, flags, err := helpers.Operation(operation)
	if err != nil {
		return err
	}

	// Run the named command as a process with the step's whole number as its
	// VALUE argument and keep its stdout as the output. The calculator alone
	// halves or doubles; the body neither computes nor interprets the result.
	output, err := helpers.Run(command, append(flags, number)...)
	if err != nil {
		return err
	}

	state.Output = output
	return nil
}

package steps

func Register(suite Registrar) {

	suite.Step("^the Owner ((?:exactly )?halves|doubles) (-?\\d+)$", conceptcc0034864638b337019c005041b6023fc84395f3cfcb85aa7757c1b208c55d6e)

	suite.Step("^the calculator's output (matches|does not match) (.+)$", concept95123e5878d35715c67b1f901cd0d6e1fcafc896021616abdece460efff6ed7e)
}
